<?php require 'config.php';$title='Track Your Order | MediHome';$order=null;$items=[];$err='';if($_SERVER['REQUEST_METHOD']==='POST'){$id=(int)($_POST['order_id']??0);$phone=trim($_POST['phone']??'');if($id<1||$phone==='')$err='Enter your order number and phone number.';else{$s=$pdo->prepare('SELECT * FROM orders WHERE id=? AND phone=? LIMIT 1');$s->execute([$id,$phone]);$order=$s->fetch();if($order){$s=$pdo->prepare('SELECT * FROM order_items WHERE order_id=?');$s->execute([$order['id']]);$items=$s->fetchAll();}else $err='We could not find an order matching those details. Please check and try again.';}}require 'includes/header.php';?>
<div class="pagehead"><span class="eyebrow">Order updates</span><h1>Track your order</h1><p>Enter your order number and the phone number used at checkout.</p></div><div class="tracking-layout"><section class="formbox tracking-form"><form method="post"><div class="field"><label for="order_id">Order number</label><input class="input" id="order_id" type="number" min="1" name="order_id" required value="<?=e($_POST['order_id']??'')?>" placeholder="e.g. 1024"></div><div class="field"><label for="phone">Phone number</label><input class="input" id="phone" type="tel" name="phone" required value="<?=e($_POST['phone']??'')?>" placeholder="Phone used for the order"></div><?php if($err):?><div class="flash error"><?=e($err)?></div><?php endif;?><button class="btn" type="submit">Find my order</button></form><p class="tracking-help">Your order number is shown after checkout and in your order history.</p></section>
<?php if($order): $steps=['Pending','Confirmed','Packed','Shipped','Delivered'];$cancelled=$order['status']==='Cancelled';$current=array_search($order['status'],$steps,true);?><section class="tracking-result"><div class="tracking-head"><div><small>ORDER NUMBER</small><h2>#<?= (int)$order['id']?></h2></div><span class="status-pill <?= $cancelled?'cancelled':'status-active' ?>"><?=e($order['status'])?></span></div><p>Placed on <?=e(date('d M Y, h:i A',strtotime($order['created_at'])))?></p><?php if($cancelled):?><div class="notice">This order has been cancelled. Contact customer support if you need help.</div><?php else:?><div class="tracking-steps"><?php foreach($steps as $i=>$step):$done=$current!==false&&$i<=$current;?><div class="tracking-step <?=$done?'done':''?>"><span class="step-dot"><?=$done?'✓':($i+1)?></span><div><strong><?=e($step)?></strong><small><?php if($i===0):?>Order received<?php elseif($i===1):?>Order confirmed<?php elseif($i===2):?>Items prepared<?php elseif($i===3):?>Handed to delivery<?php else:?>Delivered to your address<?php endif;?></small></div></div><?php endforeach;?></div><?php endif;?><div class="tracking-meta"><div><small>DELIVERY ADDRESS</small><p><?=nl2br(e($order['address']))?></p></div><div><small>PAYMENT METHOD</small><p><?=e($order['payment_method'])?></p></div><div><small>ORDER TOTAL</small><h2><?=money($order['total'])?></h2></div></div><h3>Items in this order</h3><div class="tracking-items"><?php foreach($items as $i):?><div><span><?=e($i['medicine_name'])?> × <?= (int)$i['quantity']?></span><strong><?=money((float)$i['unit_price']*(int)$i['quantity'])?></strong></div><?php endforeach;?></div></section><?php endif;?></div><?php require 'includes/footer.php';?>